import type { SyncTarget } from "@agnostic/core";

/**
 * Line 1 of every file agn generates, and the mark that says the file is agn's to rewrite. An
 * HTML comment because harnesses read the raw text and GitHub renders nothing.
 */
export const GENERATED_HEADER =
  "<!-- generated by agn sync from .ag/instructions.md; edit that file, not this one -->";

/** Claude Code imports another file with `@path`, so the instructions exist in one copy. */
const CLAUDE_IMPORT = "@AGENTS.md";

export function isGenerated(text: string): boolean {
  return text.split("\n")[0] === GENERATED_HEADER;
}

/** What goes under the header: the instructions themselves, or Claude Code's import of them. */
export function targetBody(target: SyncTarget, instructions: string): string {
  return target === "AGENTS.md" ? instructions : CLAUDE_IMPORT;
}

/** The bytes of one generated file: the header, a blank line, the body, one trailing LF. */
export function renderTarget(target: SyncTarget, instructions: string): string {
  const body = withoutTrailingNewlines(targetBody(target, instructions));
  return body === "" ? `${GENERATED_HEADER}\n` : `${GENERATED_HEADER}\n\n${body}\n`;
}

export function withoutTrailingNewlines(text: string): string {
  return text.replace(/\n+$/, "");
}
